# Texto da aba "Métodos e fontes", em markdown, usado pela página em Quarto e pelo app Shiny.
#
# Uma só fonte para os dois: a diferença está em quatro frases que dependem de como os modelos são ajustados.
#   - Quarto (resumo != NULL): todos os recortes foram ajustados antes, então o texto cita contagens e valores do recorte "Todos os locais, todas as idades".
#   - Shiny (resumo = NULL): os modelos são ajustados quando o recorte é escolhido; o texto explica isso e remete à nota abaixo da figura.

fmt <- function(x, d = 0) formatC(x, format = "f", digits = d, big.mark = ".", decimal.mark = ",")
fd <- function(x) format(as.Date(x), "%d/%m/%Y")
mm <- function(ym) paste0(substr(ym, 6, 7), "/", substr(ym, 1, 4))
rr_txt <- function(v) sprintf("%s (IC 95%%: %s a %s)", fmt(v[1], 2), fmt(v[2], 2), fmt(v[3], 2))

# Tabela de reconciliação das causas: óbitos por grupo de causa básica (soma = total de óbitos elegíveis, os da população nos dias da série),
# a que opção do seletor Causa do óbito cada grupo pertence e o detalhe dos códigos que explicam a classificação. r = M$reconc (reconciliar_causas).
tabela_reconciliacao <- function(r) {
  if (is.null(r) || is.null(r$grupos)) return("")
  rot <- c(naturais = "Naturais", todas_sem_covid = "Todas, exceto COVID-19", todas = "Todas, com COVID-19", externas = "Externas")
  g <- r$grupos
  em <- vapply(g$grupo, function(gr) paste(rot[names(CAUSA_GRUPOS)[vapply(CAUSA_GRUPOS, function(v) gr %in% v, TRUE)]], collapse = "; "), "")
  linhas <- paste0("| ", g$rotulo, " | ", fmt(g$n), " | ", em, " |\n", collapse = "")
  opc <- paste0(vapply(names(rot), function(k) paste0(rot[[k]], ": ", fmt(r$opcoes[[k]])), ""), collapse = "; ")
  det <- paste0("- ", r$detalhe$rotulo, ": ", fmt(r$detalhe$n), "\n", collapse = "")
  paste0("**Reconciliação das causas.** Dos ", fmt(r$total), " óbitos elegíveis (os da população selecionada nos dias da série), cada um pertence a um só grupo de causa básica:\n\n",
         "| Grupo de causa básica | Óbitos | Opções do seletor |\n|:--|--:|:--|\n", linhas,
         "| **Total de óbitos elegíveis** | **", fmt(r$total), "** | |\n\n",
         "Óbitos por opção do seletor: ", opc, ". Detalhe dos códigos:\n\n", det, "\n")
}

# M: meta da Figura 1 (base_figura1); n_sem_idade: óbitos sem idade informada;
# resumo: resumo_figura1() (só no Quarto); dados: list(sim_atualizado, clima_atualizado, repo_sim, gerado_em) (só no Shiny)
texto_metodos <- function(M, n_sem_idade, resumo = NULL, dados = NULL) {
  demanda <- is.null(resumo)
  pop_txt <- if (M$pop == "res") "residentes no Rio com óbito ocorrido no próprio município" else "todos os óbitos ocorridos no Rio, residentes ou não"
  nc_txt <- if (length(M$meses_nc)) paste(mm(M$meses_nc), collapse = ", ") else "nenhum"
  h <- M$exposicoes$horas$ref; a <- M$exposicoes$haat$ref
  pg <- function(...) paste0(paste0(..., collapse = ""), "\n\n")

  intro <- if (demanda)
    "Esta página apresenta a Figura 1 do painel, desenvolvido em R e Shiny. O servidor obtém os dados diretamente das Releases do GitHub e ajusta o modelo de cada recorte (combinação de filtros) no momento em que ele é selecionado (de 3 a 15 segundos na primeira solicitação). O resultado é armazenado no servidor, de modo que as consultas seguintes ao mesmo recorte, feitas por qualquer usuário, são atendidas de imediato até a próxima atualização dos dados. Cada combinação de local do óbito, faixa etária, raça/cor, causa do óbito e retiradas do ajuste tem um modelo próprio."
  else
    "Esta página apresenta a Figura 1 do painel, reescrita em R e Quarto. O processamento dos dados e o ajuste dos modelos são feitos em R (`calcular_figura1.R`), e os resultados ficam incorporados a este arquivo, que abre diretamente no navegador. Como cada recorte (combinação de local do óbito, faixa etária e raça/cor) já tem o seu modelo calculado, a troca de filtros não reestima os modelos."

  causas_p <- if (demanda)
    pg("O seletor Causa do óbito oferece quatro séries: causas naturais (padrão, definidas acima), todas as causas exceto COVID-19, todas as causas com COVID-19 e causas externas. Neste painel, causas externas são os óbitos com causa básica nos códigos V01 a Y98 da CID-10. Os códigos S00 a T98 descrevem a natureza da lesão e, pelas regras de codificação da CID-10, não deveriam ser a causa básica. Quando aparecem, assim como as causas básicas ausentes e os códigos inválidos, formam grupos próprios, que entram apenas em Todas as causas. A tabela de reconciliação, na seção Dados, mostra quantos óbitos há em cada grupo e a quais opções do seletor ele pertence. Cada causa tem a sua própria série de óbitos, e a lista de recortes com óbitos suficientes varia conforme a causa.")
  else ""
  retirar_p <- if (demanda) paste0(
    "### Retirar períodos do ajuste\n\n",
    pg("O ajuste principal é a amostra descrita em Período e registro do SIM: as caixas Meses com registro não consolidado e Dias sem dados de clima vêm marcadas, e o período da COVID-19 permanece no ajuste, com o termo `s(COVID)` absorvendo o excesso. Três caixas de seleção, no grupo Retirar do ajuste do modelo, alteram essa escolha. Cada caixa marcada exclui os dias correspondentes dos dados usados para estimar o modelo (os dias sem registro no SIM são sempre excluídos):"),
    "- Período da COVID-19 (", fd(M$covid[1]), " a ", fd(M$covid[2]), "), desmarcada por padrão: o modelo é ajustado sem esses dias e deixa de ter o termo `s(COVID)`.\n",
    "- Meses com registro não consolidado (", nc_txt, "), marcada por padrão: os dias desses meses são excluídos do ajuste. Desmarcada, é a sensibilidade em que o modelo usa esses meses, nos quais o número de óbitos observado pode estar abaixo do real.\n",
    "- Dias sem dados de clima e os ", M$lag, " seguintes, marcada por padrão: esses dias são excluídos do ajuste, junto com os ", M$lag, " dias posteriores a cada um, porque a defasagem de 0 a ", M$lag, " dias usa o clima dos dias anteriores. Desmarcada, os dias sem clima contam como dias sem calor, que é a especificação anterior do painel; ela trata a falta de medição como ausência de calor e fica disponível só como sensibilidade.\n\n",
    pg("Semanas com algum dia fora do ajuste ficam sem esperado. Cada combinação de causa e de retiradas corresponde a um modelo distinto, ajustado e armazenado no servidor na primeira solicitação. O mínimo de ", M$min_obitos, " óbitos considera apenas os dias mantidos no ajuste."))
  else ""

  curvas_p <- if (demanda) paste0(
    "### Curvas de exposição-resposta e de defasagem\n\n",
    pg("A aba Exposição-resposta e defasagem mostra, para o recorte escolhido, duas figuras obtidas do mesmo modelo que gera o esperado sem calor. A Figura 2 traz o RR acumulado em 0 a ", M$lag, " dias em função da exposição, mantida constante em todos os dias da janela, em relação a nenhuma exposição. O intervalo de confiança de 95% usa a matriz de covariância dos coeficientes da cross-basis (função `crosspred` do pacote `dlnm`). A grade de exposição vai de zero ao percentil 99 dos dias com exposição, porque acima disso há poucos dias. A Figura 3 é um gráfico de floresta, nos dois níveis de referência: a parte superior traz o RR de cada defasagem de 0 a ", M$lag, " (efeito de uma exposição ocorrida em um único dia, l dias antes do óbito, com os demais dias da janela sem exposição) e a parte inferior traz o RR acumulado de 0 até l, para l igual a 1, 3, 7 e ", M$lag, ", que supõe a exposição mantida em todos os dias de 0 a l. Só a parte inferior descreve exposição mantida; a parte superior descreve um dia isolado. O RR acumulado até l é o produto dos RR por defasagem de 0 a l, com intervalo de confiança de 95% a partir da matriz de covariância dos coeficientes, e as duas partes usam escalas horizontais diferentes. Os quadros do topo trazem o RR no mesmo dia (lag 0), para a exposição ocorrida só nesse dia, e os RR acumulados em 0 a 3 e em 0 a ", M$lag, " dias, para a exposição mantida em todos os dias da janela."),
    pg("Com a medida de horas, a resposta à exposição tem 1 grau de liberdade: o logaritmo do RR é uma reta nas horas por construção, a curva não identifica limiar nem curvatura e RR(8 h) = RR(4 h)². Os RR de 4 e de 8 horas do modelo de referência são, portanto, um só achado, lido em dois pontos da mesma reta. Para verificar se os dados sustentam essa forma, a aba refaz o ajuste do mesmo recorte, da mesma causa e com as mesmas retiradas, trocando só a função da exposição por um spline natural com 3 graus de liberdade e nós interiores em 3 e 6 horas, definidos antes da análise e sem otimização (curva flexível pré-definida). A Figura 2 desenha a curva flexível tracejada sobre a reta, com o IC 95% de cada uma, e as barras logo abaixo mostram quantos dias do ajuste têm cada número de horas, para que se veja onde há dados. O Quadro 3 traz, para a reta e para a curva flexível, os graus de liberdade, o RR com 4 e com 8 horas, o RR de 8 horas contra 4 horas, a razão entre o log RR de 8 e o de 4 horas (2 na reta), o AIC e a comparação aproximada dos dois ajustes por razão de desvios (função `anova` do `mgcv`, com a reta contida na curva flexível). Como os resíduos têm autocorrelação, o valor de p dessa comparação é indicativo. O IC da reta é mais estreito que o da curva flexível nas extremidades porque a forma está imposta, e não porque haja mais dados nessa região."),
    pg("O RR acumulado em 0 a ", M$lag, " dias descreve a exposição de referência mantida em todos os ", M$lag + 1, " dias, e a série pode quase não ter essa sequência. O Quadro 4 mostra o suporte de cada contraste. Dia com exposição é o dia com exposição de pelo menos o nível de referência (4 e 8 h por dia, ou 5 e 20 °C·h por dia; dia sem dado de clima conta como dia sem exposição), contado apenas no próprio dia, e não na janela de t a t−3 da Figura 1. Para as durações de 1, 2, 4, 8 e ", M$lag + 1, " dias, o quadro conta as janelas (dias do óbito no ajuste em que os d dias terminados nele são todos dias com exposição) e os eventos independentes (conjuntos de dias com exposição separados de outros por pelo menos ", M$lag, " dias sem exposição, de modo que as janelas de defasagem de eventos diferentes não se tocam), e traz ao lado o RR acumulado do mesmo contraste (defasagens de 0 a d-1, que supõe exposição nos d últimos dias e nenhuma antes). A duração observada das sequências de dias com exposição e a distribuição por ano (dias com exposição, sequências de 4 dias ou mais e janelas de ", M$lag + 1, " dias) completam o quadro. A coluna Leitura classifica cada linha pelo número de eventos independentes (menos de 5: extrapolação; de 5 a 29: poucos eventos; 30 ou mais: frequente), limiares que são uma convenção do painel e não um critério estatístico. O suporte depende só da exposição e dos dias do ajuste, e por isso é o mesmo em qualquer recorte; só o RR muda com o recorte."),
    pg("O HAAT usa spline penalizado de 15 graus de liberdade na exposição combinado com 3 graus de liberdade na defasagem, o que dá uma base cruzada de 45 colunas (k'). A penalização reduz a flexibilidade efetiva, e o Quadro 3 informa os graus de liberdade efetivos do ajuste ao lado de k'. A curva do HAAT é estimada, e não imposta, mas as extremidades têm poucos dias de exposição alta e intervalos largos. A aba tem filtros próprios de recorte, causa do óbito e retirada do ajuste, e reaproveita os modelos já ajustados nas outras abas."),
    pg("O seletor Comparar com (local do óbito) acrescenta um segundo recorte, que difere do primeiro apenas no local do óbito: os demais filtros valem para os dois. Os recortes aparecem em colunas, cada um com quadros, Figuras 2, 3 e 4 e interpretação próprios, e as Figuras 2 e 3 usam a mesma escala nos dois lados. O texto de comparação traz o RR acumulado dos dois locais e informa se os intervalos de confiança se sobrepõem, o que é uma comparação informal e não um teste da diferença. Quando um dos recortes é Todos os locais, ele inclui os óbitos do outro e as duas estimativas não são independentes."))
  else ""

  mapa_p <- if (demanda) paste0(
    "### Mapa de horas por dia e limiar do IC\n\n",
    pg("A Figura 4 refaz, com o modelo de referência, o mapa de horas por dia e limiar da versão anterior do painel. Para cada limiar K (32 a 44 °C) e cada número mínimo de horas H (1, 2, 3, 4, 6, 8, 10 e 12), a exposição é binária: vale 1 nos dias com pelo menos H horas de IC igual ou superior a K, e 0 nos demais, inclusive nos dias sem dado de clima. Cada célula é um modelo próprio, com o mesmo GAM da Figura 1 (binomial negativa, spline do tempo, ciclo anual e termo do período COVID) e a mesma defasagem de 0 a ", M$lag, " dias, com cross-basis linear na exposição e spline natural de 3 graus de liberdade na defasagem. O RR de cada célula é o acumulado em 0 a ", M$lag, " dias para a exposição mantida em todos os ", M$lag + 1, " dias, em relação a nenhum dia com exposição, com intervalo de confiança de 95% a partir da matriz de covariância dos coeficientes."),
    pg("A versão anterior definia a exposição como dia com exposição em t a t−3 (a condição em t, t−1, t−2 ou t−3) e estimava cada célula por quase-Poisson com termo de dia da semana. O modelo atual usa a defasagem distribuída do DLNM e não tem termo de dia da semana, de modo que os RR das duas versões não são comparáveis em valor. Células com menos de 15 dias com exposição no ajuste, ou com menos de 30 dias sem exposição, não são estimadas. As 104 células são ajustadas de forma independente, são aninhadas por construção (um dia com mais horas também entra nas definições com menos horas) e não passam por correção para comparações múltiplas; o mapa é descritivo. As colunas são calculadas sob demanda, uma por limiar, e ficam guardadas no servidor para os pedidos seguintes."),
    pg("Cada célula mostra o número de dias com exposição no ajuste (d) e o de eventos independentes (ev.), isto é, de conjuntos de dias com exposição separados por mais de ", M$lag, " dias sem exposição, de modo que as janelas de defasagem de eventos diferentes não se tocam (a mesma definição da tabela de suporte da aba Exposição-resposta). Células com poucos dias ou poucos eventos têm intervalos largos. O painel não destaca a célula de maior RR, porque o máximo de 104 estimativas correlacionadas tende a superestimar o efeito, e o texto de interpretação descreve a faixa de valores da tabela. O contorno azul marca o dia com ≥ 4 h de IC ≥ 36 °C, combinação de referência do painel, próxima do critério do NC 2 do protocolo (que usa “acima de” 36 °C)."))
  else ""

  cid_p <- if (demanda) paste0(
    "### Causas específicas (CID-10)\n\n",
    pg("A aba Causas específicas (CID-10) estima, para o recorte escolhido, o RR da contagem diária de óbitos associado à exposição ao calor para cada causa básica de óbito com 3 caracteres da CID-10. Cada causa com pelo menos ", fmt(M$cid_min), " óbitos nos dias do ajuste é avaliada em um modelo próprio, com a estrutura do modelo de referência (binomial negativa, spline do tempo, ciclo anual, termo do período da COVID-19 quando restam dias dele no ajuste e cross-basis de defasagem de 0 a ", M$lag, " dias), aplicado à série diária de óbitos daquela causa e com as mesmas retiradas do ajuste do recorte. A medida de calor e o nível de exposição (um dos dois níveis de referência) são escolhidos na aba. O RR é o acumulado em 0 a ", M$lag, " dias para a exposição mantida em todos os ", M$lag + 1, " dias, em relação a nenhuma exposição. O IC 95% usa a matriz de covariância dos coeficientes, e o valor de p vem da aproximação normal do logaritmo do RR."),
    pg("Como a aba avalia dezenas de causas de uma só vez, parte dos RR diferentes de 1 apareceria por acaso. O valor q de Benjamini e Hochberg controla a taxa de falsas descobertas dentro de duas famílias de testes definidas de antemão. A família principal reúne as causas avaliadas que pertencem aos 15 grupos do estudo de referência (Morais et al.), escritos aqui em códigos de 3 caracteres: influenza e pneumonia (J09, J12 a J18); doenças respiratórias crônicas inferiores (J40 a J47); outras doenças respiratórias (J00 a J06, J20 a J39, J60 a J70, J80 a J99, R09 e U04); doenças hipertensivas (I10 a I15); doenças isquêmicas do coração (I20 a I25); insuficiência cardíaca (I50); doenças cerebrovasculares (I60 a I69); outras doenças do aparelho circulatório (I00 a I09, I26 a I49, I51, I52 e I70 a I99); neoplasias malignas (C00 a C97); Alzheimer e demência (G30, G31, F01 e F03); diabetes (E10 a E14); insuficiência renal (N17 a N19); sepse (A40 e A41); infecção do trato urinário (N39); e causas mal definidas (capítulo R). A lista é fixa e não depende dos resultados do painel. A família exploratória reúne as demais causas avaliadas e serve para levantar hipóteses. Não há correção conjunta entre as duas famílias."),
    pg("Todas as estimativas ficam visíveis por padrão, cada uma com o q da sua família. O filtro de capítulo e a caixa que mostra só as causas com q < 0,05 escolhem as linhas exibidas e não alteram o q, e a linha “Mostrando m de N causas” informa quantas causas o filtro deixa à vista. A escolha entre a família principal sozinha e as duas famílias define apenas quais causas são calculadas, e não muda o q da família principal. O q muda quando mudam o recorte, a população, a medida e o nível de exposição ou as retiradas do ajuste, porque essas escolhas alteram quais causas atingem o mínimo de óbitos e os valores de p. O q de uma família só é calculado quando todas as causas dela estão estimadas. Na figura, as causas com q < 0,05 aparecem em laranja (RR acima de 1) ou azul (RR abaixo de 1), as demais em cinza, e o marcador é cheio na família principal e vazado na exploratória."),
    pg("Cada causa é pedida ao servidor separadamente, no máximo duas ao mesmo tempo, e o resultado fica guardado em disco. Por isso a figura se completa causa a causa, e a primeira abertura de um recorte leva de 3 a 10 segundos por causa. Ao clicar em uma causa, a Figura 5b mostra seus óbitos semanais observados e o esperado sem calor do modelo daquela causa, com a faixa de 95% calculada como na Figura 1. Os nomes das causas vêm do arquivo `dados_auxiliares/cid_nomes.json`, que cobre as causas de 3 caracteres avaliadas."))
  else ""

  recon_p <- tabela_reconciliacao(M$reconc)

  dia_p <- if (demanda) paste0(
    "### Diagnósticos e análises de sensibilidade\n\n",
    pg("A aba Diagnósticos e sensibilidades publica, para o recorte escolhido, os diagnósticos do modelo principal e refaz o ajuste com uma mudança por vez. O Quadro 1 traz a autocorrelação (ACF) dos resíduos de Pearson até 35 dias, que ignora os dias fora do ajuste e usa o limite aproximado de ±1,96 ÷ √n; o teste de Ljung-Box com ", 14, " defasagens, sem desconto dos graus de liberdade do modelo, de modo que o valor de p é indicativo; o `k.check` do pacote `mgcv` (índice k e valor de p, com 200 permutações e semente fixa) para cada termo suave; a dimensão da base e os graus de liberdade efetivos de cada termo e da base cruzada; a dispersão residual (χ² de Pearson dividido pelos graus de liberdade residuais, que na binomial negativa fica perto de 1 por construção); e a convergência do REML."),
    pg("O Quadro 2 refaz o ajuste do mesmo recorte, da mesma causa e com as mesmas retiradas, mudando uma escolha por vez: dia da semana como termo do modelo; spline do tempo com metade e com o dobro dos nós; defasagem máxima de 7 e de 14 dias (a janela de retirada dos dias sem clima acompanha a defasagem); quatro alternativas para o período da COVID-19 (retirado do ajuste; mantido sem termo próprio; termo não cíclico com indicador do período; termo pelos óbitos diários de COVID-19 em média móvel de 7 dias); meses não consolidados mantidos; dias sem clima contados como dias sem calor; e a especificação anterior do painel. Cada linha traz os dias e os óbitos no ajuste, os dias com ≥ 4 h de IC ≥ 36 °C e os eventos (sequências de dias seguidos que atendem a esse critério), o RR e o IC 95% nos dois níveis de referência e o resumo do diagnóstico residual. A variação do log-RR em relação ao ajuste principal é calculada em cada nível, e variações de 20% ou mais são marcadas. A interpretação compara os valores estimados e não depende de o intervalo de confiança cruzar o 1."),
    pg("O termo `s(COVID)` do modelo de referência usa um spline cíclico sobre o índice de dias do período, com valor 0 fora dele. A natureza cíclica obriga o valor do último dia do período a coincidir com o do índice 0, e a aba mostra o valor do termo fora do período, no primeiro dia, no último e no pico. As alternativas listadas acima indicam quanto o RR depende dessa escolha."))
  else ""


  anos_txt <- paste0(substr(M$inicio, 1, 4), " a ", substr(M$fim, 1, 4))
  apres_p <- paste0(
    pg("Óbitos ocorridos no município do Rio de Janeiro e exposição ao calor, de ", anos_txt, ". Estudo ecológico de série temporal. Os modelos estimam a associação entre o Índice de Calor (IC) e a contagem diária de óbitos, após ajuste para os fatores descritos em Métodos e fontes."),
    pg("O estudo é ecológico porque a unidade de análise é o dia no município, com a contagem diária de óbitos e uma exposição municipal agregada, e não pessoas com a sua exposição individual. É de série temporal porque compara o mesmo município ao longo do período de ", anos_txt, ". Tem componente analítico porque estima, em cada recorte, o RR da contagem diária de óbitos associado à exposição ao calor, com IC 95% e ajuste para tendência, sazonalidade e período da COVID-19, e porque examina a sensibilidade desse RR a escolhas do modelo. Os demais resultados (razão O/E, frequência de semanas acima da faixa e células do mapa de horas por limiar) são descritivos. O RR é uma associação em dados agregados, sem estimação de risco individual, e não estabelece causalidade."))

  termos_p <- paste0(
    "### Termos usados no painel\n\n",
    pg("A sigla IC designa o Índice de Calor; o intervalo de confiança aparece sempre como IC 95% e só acompanha o RR."),
    "| Termo | Significado no painel |\n|:--|:--|\n",
    "| Índice de Calor (IC) | Medida que combina temperatura e umidade, em °C, calculada pela equação do National Weather Service dos Estados Unidos (Rothfusz, 1990) sobre a média horária das estações. O painel sempre informa se o valor é o IC máximo do dia (maior valor horário) ou o IC médio do dia (média dos valores horários). Não é sinônimo de temperatura média do ar, que aparece com esse nome. |\n",
    "| Nível de Calor 1 a 5 (NC 1 a NC 5) | Níveis do protocolo municipal. O painel mostra o NC estimado retrospectivamente: reconstrução a partir das horas observadas de IC, sem previsão, que pode diferir do NC divulgado pelo Centro de Operações e Resiliência do Rio (COR). Não é sinônimo de alerta. |\n",
    "| Dia com IC máximo ≥ 36 °C | Dia em que o maior IC horário atingiu ou superou 36 °C. |\n",
    "| Dia com ≥ 4 h de IC ≥ 36 °C | Dia em que o IC horário atingiu ou superou 36 °C em pelo menos 4 horas. É o evento meteorológico no dia e o critério do NC 2. |\n",
    "| Dia com exposição em t a t−3 | Dia em que o próprio dia (t) ou um dos três anteriores (t−1 a t−3) foi um dia com ≥ 4 h de IC ≥ 36 °C. É a janela descritiva da escala diária da Figura 1, e não a janela do modelo. |\n",
    "| Dia com exposição | Nos quadros e mapas da aba Exposição-resposta, dia em que a exposição do modelo atinge o nível de referência ou o limiar da célula, contado apenas no próprio dia. |\n",
    "| Semana de calor | Semana que atende ao critério escolhido na Figura 1: pelo menos 3 dias com IC máximo ≥ 36 °C, ou pelo menos um dia em NC 2 a NC 5 estimado retrospectivamente. |\n",
    "| RR da contagem diária de óbitos | Razão entre a contagem diária de óbitos esperada com a exposição indicada e a esperada sem ela, acumulada em 0 a ", M$lag, " dias. É uma associação em dados agregados, sem estimação de risco individual. |\n",
    "| Óbitos observados e esperados sem calor | O esperado é o número de óbitos que o modelo prevê com exposição zero em todas as defasagens. A diferença entre observado e esperado é descritiva e não é uma estimativa formal de óbitos atribuíveis ao calor. |\n",
    "| Razão observado/esperado sem calor (O/E) | Soma dos óbitos observados dividida pela soma dos esperados sem calor, em um grupo de semanas ou de dias. Medida descritiva, sem IC 95%, separada do RR. |\n",
    "| Faixa aproximada de variação de 95% | Faixa em torno do esperado de uma semana ou de um dia. Não incorpora toda a incerteza dos parâmetros e por isso não leva o nome de IC 95%. |\n",
    "| Local do óbito | Lugar de ocorrência do óbito. Não identifica a residência nem a exposição individual. |\n\n")

  protocolo_p <- paste0(
    "### Correspondência com o protocolo municipal\n\n",
    pg("O Protocolo de Enfrentamento ao Calor Extremo da Secretaria Municipal de Saúde do Rio de Janeiro distingue a medida meteorológica IC, os Níveis de Calor (NC 1 a NC 5) e as ações de preparação, monitoramento, alerta e resposta. O painel analisa retrospectivamente óbitos e exposições estimadas; seus resultados não são alertas operacionais nem a classificação oficial divulgada pelo COR."),
    pg("O Quadro 1 da página 6 do protocolo define NC 1 a NC 5 com critérios de IC, duração e, nos níveis superiores, previsão ou registro de dias adicionais. O protocolo usa “acima de” 36, 40 e 44 °C; o painel usa “≥”, e essa diferença consta junto da legenda dos níveis. O Quadro 3 da página 10 associa os níveis a fases de gestão de riscos, e o painel não transpõe essas fases, porque as estimativas retrospectivas não acionam medidas operacionais."),
    pg("Níveis de Calor (NC 1 a NC 5) estimados retrospectivamente a partir das horas observadas de IC. Esta reconstrução não incorpora previsão meteorológica e pode diferir do NC monitorado e divulgado pelo COR. O documento municipal usa dados do Alerta Rio, do INMET e da REDMET na construção de suas séries, e o painel usa o Alerta Rio e o INMET, o que também pode explicar diferenças."),
    pg("O protocolo relata efeitos durante o evento ou até três dias depois. O painel usa um DLNM de 0 a ", M$lag, " dias, e essa janela é uma decisão do modelo, sem relação com a janela de três dias do protocolo. Na escala diária da Figura 1, a janela descritiva de t a t−3 marca os dias em que o evento ocorreu no próprio dia ou nos três anteriores."),
    pg("Fonte terminológica: Secretaria Municipal de Saúde do Rio de Janeiro. Protocolo de Enfrentamento ao Calor Extremo, 2024, pp. 4 a 7 e 10, especialmente Quadros 1 e 3."))

  ficha_p <- paste0(
    "### Ficha de cada resultado\n\n",
    pg("Junto de cada resultado, uma ficha informa a versão dos dados, a população, o recorte (local do óbito, faixa etária e raça/cor), a causa do óbito, o período e a amostra do ajuste, a medida de calor e a defasagem, as retiradas do ajuste, a família do modelo (binomial negativa ou quase-Poisson) e as ressalvas", if (demanda) ", e, nas abas Exposição-resposta, Causas específicas e Diagnósticos, as particularidades de cada análise. Os arquivos CSV da Figura 1 trazem as mesmas informações nas linhas iniciadas por #." else ". O arquivo CSV traz as mesmas informações nas linhas iniciadas por #."))

  pop_frase <- if (demanda) "A população selecionada corresponde a" else "A população desta versão corresponde a"

  trocas <- if (demanda)
    "A família binomial negativa é a padrão. Em séries muito esparsas, nas quais ela não converge, o ajuste usa a família quase-Poisson, e a nota abaixo da figura informa a família utilizada em cada recorte."
  else
    paste0("Séries muito esparsas, nas quais a binomial negativa não converge, usam a família quase-Poisson. ",
           if (sum(unlist(resumo$n_qp)) == 0) "Nesta execução, nenhum dos " else paste0("Nesta execução, ", sum(unlist(resumo$n_qp)), " dos "),
           fmt(2 * resumo$n_segmentos), if (sum(unlist(resumo$n_qp)) <= 1) " ajustes precisou dessa troca." else " ajustes precisaram dessa troca.")

  rr_frase <- paste0("RR acumulado em 0 a ", M$lag, " dias: exposição de ", h[1], " h diárias com IC ≥ 36 °C (ou de ", h[2], " h) mantida por ", M$lag + 1, " dias, em comparação com ausência dessa exposição no mesmo intervalo. É uma estimativa do modelo ajustado, e não uma medida de risco individual.",
                     if (!demanda) paste0(" Para todos os locais e idades, o RR com ", h[1], " h por dia é ", rr_txt(resumo$rr_total$horas[1:3]),
                                          " e com ", h[2], " h por dia é ", rr_txt(resumo$rr_total$horas[4:6]), "."))

  phi_frase <- if (demanda) "O valor de φ de cada recorte aparece na nota abaixo da figura."
               else paste0("Para todos os locais e idades, φ é ", fmt(resumo$phi_total$horas, 2), ".")

  repro <- if (demanda)
    paste0("```\nRscript shiny/atualizar_cache.R\n```\n\nO aplicativo Shiny e a página em Quarto utilizam as mesmas funções de R (pasta `R/`); assim, o mesmo recorte produz o mesmo resultado nos dois. ",
           "Pacotes de R: `shiny`, `mgcv`, `dlnm`, `nanoparquet`, `jsonlite`, `future` e `promises`.")
  else
    paste0("```\nRscript calcular_figura1.R --silver entrada/sim/silver --haat entrada/haat_diario_municipal.csv\nquarto render painel_figura1.qmd\n```\n\n",
           "Pacotes de R: `mgcv`, `dlnm`, `nanoparquet`, `jsonlite`, `knitr`.")
  versao <- if (demanda)
    paste0(" Fonte e data da extração: SIM atualizado em ", dados$sim_atualizado, " (", dados$repo_sim, ") e clima atualizado em ", dados$clima_atualizado, " (horários em UTC); cache gerado em ", dados$gerado_em, ".")
  else paste0(" Versão dos dados desta página: gerada em ", M$gerado_em, ".")

  paste0(
    "## Métodos e fontes\n\n",
    pg(intro),
    apres_p,
    termos_p,
    protocolo_p,
    ficha_p,
    "### Dados\n\n",
    pg("Os óbitos provêm do Sistema de Informações sobre Mortalidade (SIM/DATASUS), por meio do repositório de dados (data lake) do projeto, em sua camada silver, com os óbitos ocorridos no município do Rio de Janeiro desde 2006. ",
        pop_frase, " ", pop_txt, ": ", fmt(M$n_obitos), " óbitos por causas naturais entre ", fd(M$inicio), " e ", fd(M$fim),
        ". Causa natural é aquela registrada nos capítulos I a XVIII da CID-10 (códigos A00 a R99), exceto a COVID-19. A COVID-19 é identificada pelo código completo da causa básica: B34.2 (infecção por coronavírus de localização não especificada, usada no início de 2020) e U07 (U07.1 e U07.2). Os demais códigos B34 (B34.0, B34.1 e B34.3 a B34.9), que são outras infecções virais, permanecem nas causas naturais", if (demanda) "." else ". Os óbitos por COVID-19 ficam fora de todas as séries."),
    causas_p,
    recon_p,
    pg("O local do óbito parte do campo LOCOCOR do SIM e é refinado pelo tipo de estabelecimento registrado no Cadastro Nacional de Estabelecimentos de Saúde (CNES): os tipos 5, 7, 15 e 62 correspondem a Hospital; os tipos 20, 21 e 73, a UPA / pronto atendimento (UPA: Unidade de Pronto Atendimento); e os demais estabelecimentos de saúde, a Outros estabelecimentos. Domicílio, via pública, outros locais e ignorado são os registrados diretamente no LOCOCOR. O local corresponde ao lugar de ocorrência do óbito. Diferenças entre grupos devem ser avaliadas com teste de interação; os RR apresentados separadamente não estabelecem, por si só, que um grupo tenha associação maior. O painel não faz esse teste nem ajusta a composição dos grupos (por exemplo, idade e causa), de modo que comparações entre locais, faixas etárias ou categorias de raça/cor são descritivas."),
    pg("As faixas etárias, definidas para este estudo, são 0-4, 5-9, 10-19, 20-29, 30-39, 40-49, 50-59, 60-69, 70-79 e 80 anos ou mais. Os ", fmt(n_sem_idade), " óbitos sem idade informada entram apenas em Todas as idades."),
    pg("A raça/cor provém do campo RACACOR. Branca, preta e parda têm série própria, e o agregado PPI reúne preta, parda e indígena. As categorias indígena e amarela não têm óbitos suficientes para série própria, e os óbitos com raça/cor ignorada ou não informada entram apenas em Todas. As séries por raça/cor são calculadas para todas as idades."),
    pg("O clima é a série diária municipal `haat_diario_municipal.csv`, calculada a partir do repositório de dados climáticos do projeto (Instituto Nacional de Meteorologia, INMET, e Alerta Rio): média horária das estações, IC pela equação do National Weather Service dos Estados Unidos (Rothfusz, 1990) e horas acima de cada limiar (HAAT). A metodologia segue Morais et al. (repositório *heat_mortality_MRJ_article*, usado com autorização). Há dados de clima a partir de 17/04/2007. Dia sem dado de clima (", fmt(M$dias_sem_clima), " dias na série) é dado ausente, e não dia sem calor: no ajuste principal esses dias e os ", M$lag, " seguintes ficam fora do modelo, e os óbitos deles continuam nos gráficos."),
    "### Período e registro do SIM\n\n",
    pg("A série termina na menor das duas datas: o último dia com óbito registrado no SIM e o último dia com dados de clima. Os dias sem nenhum óbito registrado (", fmt(M$dias_sem_registro),
        " dias) correspondem a arquivo ainda não carregado: são excluídos do ajuste e aparecem em cinza claro."),
    pg("Um mês é classificado como de registro não consolidado quando atende a pelo menos uma de três regras, todas baseadas na completude do registro e nenhuma no valor do RR: (1) a taxa diária de óbitos é inferior a 80% da mediana dos 12 meses de referência anteriores; (2) há pelo menos um dia sem nenhum óbito entre o primeiro e o último dia do arquivo; (3) é o último mês do arquivo e este termina antes do último dia do mês. A taxa do mês é o número de óbitos dividido pelo número de dias com algum óbito registrado; os meses do período da COVID-19 e os já classificados como não consolidados não compõem a referência. Nesta versão, os meses não consolidados são ", nc_txt, " (", fmt(M$dias_nc), " dias)", if (demanda) ". Eles aparecem hachurados nos gráficos" else ", hachurados nos gráficos", "."),
    pg("A amostra principal do ajuste retira, além dos dias sem registro no SIM, os meses não consolidados e os dias sem dado de clima com os ", M$lag, " seguintes. O período da COVID-19 permanece no ajuste, com o termo `s(COVID)`. Os óbitos dos dias retirados continuam nos gráficos e são contados à parte, por motivo, na nota abaixo da figura.", if (demanda) " Abaixo da Figura 1, uma tabela fixa compara a amostra principal com a sensibilidade em que os meses não consolidados são mantidos, com o RR e o IC 95% nos dois níveis de referência, o período estimado e o número de dias e de óbitos de cada ajuste; o título da figura informa o período efetivamente estimado." else "", " O painel não dispõe de uma versão consolidada do SIM para comparar a completude dos meses recentes, o que é uma limitação do critério."),
    pg("A seleção de anos da Figura 1 (período exibido) altera só o que é mostrado. Os óbitos, as razões O/E e as frequências de semanas acima da faixa são calculados para o período exibido; os RR, as curvas e o esperado sem calor vêm do modelo ajustado com a série completa do recorte, e os cartões indicam a qual dos dois grupos pertencem."),
    "### O modelo\n\n",
    pg("Cada recorte (local do óbito por faixa etária, ou local do óbito por raça/cor) e cada medida de calor têm um modelo próprio, adaptado do modelo de Morais et al. (script `02_model_fitting.R` do repositório citado acima): um modelo aditivo generalizado (GAM) com defasagens distribuídas (DLNM), ajustado com `mgcv::gam` por máxima verossimilhança restrita (REML). Os óbitos de cada dia seguem uma distribuição binomial negativa:"),
    "```\nlog(mu_t) = a + cb(calor, defasagem 0 a 10) + s(tempo) + s(dia do ano) + s(COVID)\n```\n\n",
    "- `cb` é a base cruzada (cross-basis) do pacote `dlnm`: uma função da exposição ao calor combinada com uma função da defasagem (spline natural com 3 graus de liberdade, gl), de 0 a ", M$lag, " dias.\n",
    "- `s(tempo)` é um spline de placa fina com base de dimensão k = ", M$k_tempo, ", que acompanha a tendência de longo prazo. O modelo de referência usa k = 12 para 12,5 anos; aqui, k cresce na mesma proporção para a série mais longa.\n",
    "- `s(dia do ano)` é um spline cíclico com base de dimensão k = 6 (sazonalidade anual).\n",
    "- `s(COVID)` é um spline cíclico com base de dimensão k = 8 sobre o número de dias desde o início do período da COVID-19 (", fd(M$covid[1]), " a ", fd(M$covid[2]), "), com valor zero fora dele.", if (demanda) " Se a caixa do período da COVID-19 estiver marcada, esse termo é retirado do modelo.", "\n",
    "- O modelo não inclui termo de dia da semana, como no modelo de referência.\n\n",
    pg(trocas),
    pg("O seletor oferece duas medidas de calor:"),
    "| Medida | Variável | Resposta à exposição | Níveis de referência do RR |\n|:--|:--|:--|:--|\n",
    "| Horas | horas do dia com IC ≥ 36 °C | spline natural, 1 gl | ", h[1], " e ", h[2], " h por dia |\n",
    "| HAAT | graus-hora de IC acima de 36 °C no dia (`auc36`) | spline penalizado, 15 gl | ", a[1], " e ", a[2], " °C·h por dia |\n\n",
    pg(rr_frase),
    retirar_p,
    curvas_p,
    mapa_p,
    cid_p,
    dia_p,
    "### Esperado sem calor\n\n",
    pg("O esperado de cada dia é o preditor linear do modelo com a cross-basis substituída pela cross-basis de exposição zero em todas as defasagens, isto é, o número de óbitos que o modelo prevê na ausência de calor (contrafactual). O esperado semanal é a soma dos sete esperados diários da semana (semanas epidemiológicas completas, de domingo a sábado). A faixa aproximada de variação de 95% é o esperado semanal ± 1,96 desvios-padrão, com aproximação normal e variância igual à soma das variâncias diárias (μ + μ²/θ) multiplicada por uma dispersão semanal φ (no mínimo 1). Dias vizinhos têm resíduos correlacionados, por epidemias e outros eventos que o modelo não descreve, e a soma de variâncias independentes subestima a variância da semana. O fator φ é a razão entre o erro quadrático semanal e essa soma, medida nos resíduos do modelo ajustado e fora do período da COVID-19. ",
        phi_frase, " Semanas com algum dia fora do ajuste ficam sem esperado."),
    pg("Três intervalos diferentes se confundem com facilidade. O intervalo de confiança do esperado mede a incerteza dos coeficientes sobre o número médio de óbitos sem calor. O intervalo preditivo mede onde pode cair o número de óbitos de uma semana, e reúne a variação aleatória dos óbitos e a incerteza dos coeficientes. A faixa do painel aproxima o intervalo preditivo com a variação aleatória e o φ, e deixa de fora a incerteza dos coeficientes. Por isso o painel usa o nome faixa aproximada de variação de 95%, e reserva IC 95% para o RR. A faixa não tem cobertura nominal garantida."),
    if (demanda) pg("O Quadro 5 da Figura 1 mostra, por período e por grupo de semanas (semanas de calor e demais), a proporção de semanas com o observado dentro, acima e abaixo da faixa. Os períodos são 2006 a 2010, 2011 a 2014, 2015 a 2019, 2020 a 2022 e 2023 em diante (ano epidemiológico da semana). Na primeira parte do quadro, a contagem usa a faixa da Figura 1, cujo modelo e cujo φ foram estimados com a série completa. Na segunda parte, pedida pelo usuário, o servidor retira cada período do ajuste, refaz o modelo com os demais anos, prevê o esperado sem calor das semanas retiradas e estima o φ só nas semanas que ficaram no ajuste. Os períodos do meio são previstos pela tendência dos vizinhos (interpolação), e o primeiro e o último, por extrapolação da tendência; o quadro marca esses dois com †. A especificação do modelo (graus de liberdade e defasagem) foi escolhida com a série completa, e por isso o quadro não é uma validação independente. Nas semanas de calor, os óbitos acima do limite superior misturam falta de calibração e efeito do calor; a calibração se lê nas demais semanas. A incerteza dos coeficientes do esperado semanal é estimada pelo método delta, com a matriz de covariância dos coeficientes condicional aos parâmetros de suavização, e o quadro informa quanto ela alargaria a faixa no ajuste principal."),
    pg("Como cada recorte tem modelo próprio, o esperado e a razão observado/esperado sem calor (O/E) variam conforme os filtros selecionados."),
    pg("Na Figura 1, a disposição padrão separa o gráfico de óbitos (observado, esperado sem calor, faixa aproximada de variação de 95% e semanas de calor) do painel de clima (valor diário escolhido, com as cores dos níveis de calor ou de um limiar), logo abaixo e com o mesmo eixo do tempo. A opção Sobrepostos recoloca as colunas de clima ao fundo do gráfico de óbitos, em um segundo eixo vertical."),
    "### Comparação entre semanas de calor e as demais\n\n",
    pg("Semana de calor é aquela com pelo menos 3 dias com IC máximo ≥ 36 °C (ou com pelo menos um dia em NC 2 a NC 5 estimado retrospectivamente, conforme o critério selecionado). A razão observado/esperado sem calor (O/E) é a soma dos óbitos observados dividida pela soma dos esperados sem calor nas semanas do grupo, excluídas as semanas do período da COVID-19, as sem registro no SIM e as sem dados de clima. A O/E é uma medida descritiva: compara somas de óbitos, não tem intervalo de confiança e não é o RR do modelo, que estima a associação com IC 95%. Os cartões e as figuras do painel mantêm as duas medidas separadas (borda azul e etiqueta “RR do modelo” para o RR; borda tracejada e etiqueta “Descritivo, não é RR” para a O/E e para a frequência de semanas acima da faixa). Na escala diária, o dia com exposição em t a t−3 é o dia com ≥ 4 h de IC ≥ 36 °C e os três dias seguintes. Como o modelo usa defasagens de até ", M$lag, " dias, parte do efeito ocorre também em dias fora desse intervalo de quatro dias."),
    "### Diferença em relação à versão anterior da Figura 1\n\n",
    pg("Na versão anterior da Figura 1 semanal, o esperado vinha de um modelo apenas de tendência e sazonalidade, sem a variável de calor, ajustado a todas as semanas. Como esse modelo se ajusta à média dos dados, inclusive nas semanas de calor, a razão observado/esperado sem calor (O/E) ficava próxima de 1,00 em qualquer recorte. Nesta versão, o esperado é o contrafactual de um modelo que estima o efeito do calor em cada recorte, e a O/E nas semanas de calor reflete esse efeito.", if (demanda) " Todas as abas do painel usam agora esse mesmo modelo (GAM com DLNM)." else ""),
    "### Limitações\n\n",
    "- É um estudo ecológico de série temporal, com componente analítico: o RR descreve a associação entre a exposição municipal e a contagem diária de óbitos, e não risco individual nem causalidade. As medidas descritivas (O/E, frequência de semanas acima da faixa e células do mapa) não substituem o RR.\n",
    "- A exposição é uma série municipal agregada, calculada com a média das estações. Ela não reflete a variação de exposição entre bairros nem entre pessoas, e o local do óbito não identifica a residência.\n",
    "- A rede de estações mudou ao longo da série, e o painel não ajusta essa mudança, que pode alterar o IC e as horas acima dos limiares ao longo do tempo.\n",
    "- O confundimento residual não está excluído. O modelo ajusta tendência, sazonalidade e período da COVID-19, mas não inclui, por exemplo, poluição do ar, epidemias de doenças respiratórias, feriados nem dia da semana.\n",
    "- A janela de defasagem de 0 a ", M$lag, " dias é uma decisão de modelagem do painel. Ela não vem da janela de três dias do protocolo municipal.\n",
    "- Diferenças entre locais do óbito, faixas etárias ou categorias de raça/cor não são testadas por interação, e a composição dos grupos não é ajustada.\n",
    "- Cada recorte tem um modelo próprio, sem correção para comparações múltiplas. Recortes com poucos óbitos (mínimo de ", M$min_obitos, " no ajuste) produzem RR instáveis, com intervalos de confiança largos.\n",
    "- A faixa aproximada de variação de 95% não inclui a incerteza dos coeficientes, usa aproximação normal e um único φ para toda a série. A cobertura varia entre períodos", if (demanda) " (Quadro 5)" else "", " e não é garantida em 95%.\n",
    if (demanda) "- Quando o Quadro 1 da aba Diagnósticos e sensibilidades mostra autocorrelação dos resíduos (é o caso do ajuste principal para todos os locais e idades), os IC 95% dos RR, calculados como se os resíduos fossem independentes, podem ser estreitos demais. A dispersão φ semanal corrige só a faixa da Figura 1, e nenhuma das análises de sensibilidade remove essa dependência.\n",
    "- O período da COVID-19 é absorvido por um termo suave; por isso, o esperado nesse período não serve de comparação, e as semanas e os dias desse período ficam fora dos indicadores.", if (demanda) " Se a caixa de retirada estiver marcada, o período fica sem esperado.", "\n",
    if (demanda) "- Os modelos analisam contagens de óbitos, sem taxas por população: a população não entra como offset, e o spline de tempo absorve a variação lenta dela ao longo dos anos. A comparação de níveis entre populações ou entre anos exigiria taxas; o RR independe dessa limitação.\n",
    "- Não há dados de clima antes de 17/04/2007, e há falhas posteriores. Esses dias e os ", M$lag, " seguintes ficam fora do ajuste principal. A exclusão não corrige dias com poucas horas de medição, nos quais a contagem de horas de calor pode estar subestimada.\n",
    "- A classificação de mês não consolidado depende da própria série de óbitos e de uma referência de 12 meses; não foi comparada com uma versão consolidada do SIM.\n",
    "\n",
    "### Reprodução\n\n",
    repro, versao, "\n\n",
    "A paleta de cores foi adaptada do site EpiRio (Centro de Inteligência Epidemiológica, Prefeitura do Rio). Os gráficos são gerados com a biblioteca Chart.js 4.4.1, incorporada ", if (demanda) "a este painel" else "a este arquivo", ".\n")
}
